const INVENTORY_KEY="fridgeflow.inventory.v1",SHOPPING_KEY="fridgeflow.shopping.v1",SAVED_KEY="fridgeflow.saved.v1",HISTORY_KEY="fridgeflow.history.v1";
const categoryIcon={"蔬菜":"🥬","水果":"🍋","肉蛋":"🥚","乳制品":"🥛","主食":"🌾","调味料":"🫙","其他":"◌"};
const recipes=[
  {id:"tomato-egg",name:"番茄鸡蛋面",minutes:20,type:"protein",ingredients:["番茄","鸡蛋","面条"],note:"酸甜番茄与滑嫩鸡蛋，适合忙碌晚上的快速热食。",steps:["番茄切块，鸡蛋打散并加少许盐。","先炒鸡蛋至刚凝固，盛出备用。","番茄炒软出汁，加水煮开后放入面条。","面条熟后倒回鸡蛋，调味即可。"]},
  {id:"mushroom-rice",name:"菌菇青菜焖饭",minutes:35,type:"vegetarian",ingredients:["蘑菇","青菜","米饭"],note:"一锅完成，优先消耗容易失水的菌菇和绿叶菜。",steps:["蘑菇切片，青菜洗净切段。","锅中少油炒香蘑菇，加少许生抽。","放入米饭和少量水，加盖焖十分钟。","最后拌入青菜，焖两分钟后调味。"]},
  {id:"lemon-chicken",name:"柠檬香煎鸡胸",minutes:30,type:"protein",ingredients:["鸡胸肉","柠檬","西兰花"],note:"清爽高蛋白组合，适合希望吃得轻盈但有饱腹感的晚上。",steps:["鸡胸肉拍薄，用盐与黑胡椒腌十分钟。","西兰花焯水后沥干。","中火将鸡胸两面煎至金黄熟透。","关火挤入柠檬汁，与西兰花一起装盘。"]},
  {id:"tofu-soup",name:"豆腐菌菇汤",minutes:25,type:"vegetarian",ingredients:["豆腐","蘑菇","青菜"],note:"温和清淡，用一锅汤处理多种即将到期的食材。",steps:["豆腐切块，蘑菇切片，青菜洗净。","蘑菇下锅略炒，加适量热水。","水开后加入豆腐，小火煮十分钟。","加入青菜煮软，用盐和胡椒调味。"]},
  {id:"avocado-toast",name:"牛油果鸡蛋吐司",minutes:15,type:"protein",ingredients:["牛油果","鸡蛋","面包"],note:"十五分钟完成的轻食，适合早餐或不想开火的晚上。",steps:["鸡蛋煮熟或煎至喜欢的熟度。","牛油果压成泥，加少许盐和柠檬汁。","面包烤至边缘微脆。","抹上牛油果泥，放上鸡蛋即可。"]},
  {id:"potato-curry",name:"洋葱土豆咖喱饭",minutes:45,type:"vegetarian",ingredients:["土豆","洋葱","胡萝卜","米饭"],note:"耐储食材也需要轮换，一锅咖喱可以顺便准备明天的午餐。",steps:["土豆、洋葱和胡萝卜切成小块。","洋葱炒香后加入土豆和胡萝卜翻炒。","加水没过食材，煮至土豆变软。","关小火加入咖喱块，搅匀后搭配米饭。"]},
  {id:"tomato-mushroom",name:"番茄蘑菇烩饭",minutes:30,type:"vegetarian",ingredients:["番茄","蘑菇","米饭"],note:"番茄的酸味让菌菇更鲜，特别适合处理快到期的蘑菇。",steps:["番茄切丁，蘑菇切片。","蘑菇炒至微微上色，加入番茄炒出汁。","加入米饭和少量水，小火焖八分钟。","收汁后用盐和黑胡椒调味。"]}
];

const dialog=document.querySelector("#ingredientDialog"),form=document.querySelector("#ingredientForm");
let inventory=loadList(INVENTORY_KEY,createDemo()),shopping=loadList(SHOPPING_KEY,[{id:1,name:"燕麦",bought:false},{id:2,name:"酸奶",bought:true}]),history=loadList(HISTORY_KEY,[]),savedCount=Number(localStorage.getItem(SAVED_KEY))||0,inventoryFilter="all",inventorySearch="",inventorySort="expiry",activeRecipe=null,rankedRecipes=[],timerSeconds=0,timerHandle=null;

function dateAfter(days){const date=new Date();date.setDate(date.getDate()+days);return localDate(date)}
function localDate(date){return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function createDemo(){return[
  {id:1,name:"番茄",category:"蔬菜",quantity:3,unit:"个",expiry:dateAfter(2),location:"冷藏室"},
  {id:2,name:"鸡蛋",category:"肉蛋",quantity:6,unit:"个",expiry:dateAfter(9),location:"冷藏室"},
  {id:3,name:"蘑菇",category:"蔬菜",quantity:1,unit:"盒",expiry:dateAfter(1),location:"冷藏室"},
  {id:4,name:"青菜",category:"蔬菜",quantity:2,unit:"份",expiry:dateAfter(3),location:"冷藏室"},
  {id:5,name:"米饭",category:"主食",quantity:4,unit:"份",expiry:dateAfter(120),location:"常温储物"},
  {id:6,name:"柠檬",category:"水果",quantity:2,unit:"个",expiry:dateAfter(7),location:"冷藏室"}
]}
function loadList(key,fallback){try{const data=JSON.parse(localStorage.getItem(key));return Array.isArray(data)?data:fallback}catch{return fallback}}
function save(){try{localStorage.setItem(INVENTORY_KEY,JSON.stringify(inventory));localStorage.setItem(SHOPPING_KEY,JSON.stringify(shopping));localStorage.setItem(HISTORY_KEY,JSON.stringify(history));localStorage.setItem(SAVED_KEY,String(savedCount))}catch{toast("浏览器存储空间不足，请先导出档案。")}}
function esc(value){return String(value).replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function daysUntil(value){const today=new Date(`${localDate(new Date())}T00:00:00`),date=new Date(`${value}T00:00:00`);return Math.ceil((date-today)/86400000)}
function expiryLabel(item){const days=daysUntil(item.expiry);if(days<0)return{label:`已过期 ${Math.abs(days)} 天`,soon:true};if(days===0)return{label:"今天到期",soon:true};if(days<=3)return{label:`还剩 ${days} 天`,soon:true};return{label:`${days} 天后`,soon:false}}
function toast(message){const node=document.querySelector("#toast");node.textContent=message;node.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove("show"),2200)}
function nextId(list){return list.reduce((max,item)=>Math.max(max,Number(item.id)||0),0)+1}
function normalizeName(value){return String(value).trim().replace(/\s+/g,"").toLowerCase()}
function hasIngredient(name){const needle=normalizeName(name);return inventory.some(item=>normalizeName(item.name).includes(needle)||needle.includes(normalizeName(item.name)))}

function render(){renderInventory();renderShopping();renderHistory();renderMetrics();document.querySelector("#savedCount").textContent=savedCount;renderHero()}
function renderHero(){const urgent=[...inventory].sort((a,b)=>daysUntil(a.expiry)-daysUntil(b.expiry))[0];document.querySelector("#heroTitle").textContent=urgent?`先用掉${urgent.name}`:"给冰箱补充一点新鲜食材";document.querySelector("#heroCopy").textContent=urgent?`${expiryLabel(urgent).label}，今晚的建议会优先把它安排进去。`:"添加食材后，Agent 会根据保质期给出建议。"}
function filteredInventory(){const filtered=inventory.filter(item=>(inventoryFilter==="all"||(inventoryFilter==="soon"?daysUntil(item.expiry)<=3:daysUntil(item.expiry)>3))&&normalizeName(item.name).includes(normalizeName(inventorySearch)));return filtered.sort((a,b)=>inventorySort==="name"?a.name.localeCompare(b.name,"zh-CN"):inventorySort==="category"?a.category.localeCompare(b.category,"zh-CN")||a.expiry.localeCompare(b.expiry):a.expiry.localeCompare(b.expiry))}
function renderInventory(){const host=document.querySelector("#inventoryList"),list=filteredInventory();host.innerHTML=list.map(item=>{const status=expiryLabel(item);return`<article class="ingredient"><span class="ingredient-icon">${categoryIcon[item.category]||"◌"}</span><div><b>${esc(item.name)}</b><small>${item.quantity} ${esc(item.unit)} · ${esc(item.location)} · 至 ${item.expiry.slice(5).replace("-","/")}</small></div><div class="ingredient-status"><span class="expiry ${status.soon?"soon":""}">${status.label}</span><div class="ingredient-menu"><button onclick="useIngredient(${item.id})" title="使用一份">使用</button><button onclick="editIngredient(${item.id})" title="编辑">编辑</button><button onclick="removeIngredient(${item.id})" title="删除">×</button></div></div></article>`}).join("")||'<p class="empty-list">没有找到符合条件的食材。</p>'}
function renderMetrics(){const soon=inventory.filter(item=>daysUntil(item.expiry)<=3).length,possible=recipes.filter(recipe=>recipe.ingredients.every(hasIngredient)).length,pending=shopping.filter(item=>!item.bought).length;document.querySelector("#totalItems").textContent=inventory.length;document.querySelector("#expiringItems").textContent=soon;document.querySelector("#possibleMeals").textContent=possible;document.querySelector("#shoppingCount").textContent=pending}
function renderShopping(){const host=document.querySelector("#shoppingList");host.innerHTML=shopping.map(item=>`<label class="shop-item ${item.bought?"bought":""}"><input type="checkbox" ${item.bought?"checked":""} onchange="toggleShopping(${item.id})"><span>${esc(item.name)}</span><button type="button" onclick="removeShopping(${item.id})" aria-label="删除${esc(item.name)}">×</button></label>`).join("")||'<p class="empty-list">清单是空的，冰箱状态不错。</p>'}
function renderHistory(){const host=document.querySelector("#historyList");host.innerHTML=history.slice(0,9).map(item=>`<article class="history-item"><b>${esc(item.name)}</b><span>${new Date(item.cookedAt).toLocaleString("zh-CN")} · ${item.servings} 人份</span><small>${item.rescued?`及时使用 ${item.rescued} 份快到期食材`:"库存已同步扣减"}</small></article>`).join("")||'<p class="empty-list">完成一道菜后，它会出现在这里。</p>'}

function openForm(item=null){form.reset();form.elements.id.value=item?.id||"";document.querySelector("#dialogKicker").textContent=item?"EDIT INGREDIENT":"NEW INGREDIENT";document.querySelector("#dialogTitle").textContent=item?"编辑食材":"添加食材";document.querySelector("#saveIngredient").textContent=item?"保存修改":"保存食材";if(item)for(const key of ["name","category","quantity","unit","expiry","location"])form.elements[key].value=item[key];else form.elements.expiry.value=dateAfter(5);dialog.showModal()}
document.querySelector("#openIngredient").onclick=()=>openForm();document.querySelector("#closeDialog").onclick=document.querySelector("#cancelDialog").onclick=()=>dialog.close();
form.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form)),id=Number(data.id),item={id:id||nextId(inventory),name:String(data.name).trim().slice(0,50),category:data.category,quantity:Number(data.quantity),unit:data.unit,expiry:data.expiry,location:data.location};if(!item.name||!item.expiry||!Number.isFinite(item.quantity)||item.quantity<=0){toast("请完整填写食材信息。");return}if(id)inventory=inventory.map(entry=>entry.id===id?item:entry);else inventory.push(item);save();render();dialog.close();toast(id?`${item.name}已更新`:`${item.name}已放入冰箱`)};
window.editIngredient=id=>openForm(inventory.find(item=>item.id===id));
window.removeIngredient=id=>{const item=inventory.find(entry=>entry.id===id);if(!item||!confirm(`从冰箱记录中删除“${item.name}”吗？`))return;inventory=inventory.filter(entry=>entry.id!==id);save();render();toast("食材记录已删除")};
window.useIngredient=id=>{const item=inventory.find(entry=>entry.id===id);if(!item)return;const urgent=daysUntil(item.expiry)<=3;item.quantity=Math.round((item.quantity-1)*10)/10;if(item.quantity<=0)inventory=inventory.filter(entry=>entry.id!==id);if(urgent)savedCount+=1;save();render();toast(`已使用一份${item.name}`)};

function rankRecipes(){const limit=Number(document.querySelector("#timeLimit").value),preference=document.querySelector("#preference").value;return recipes.filter(recipe=>recipe.minutes<=limit&&(preference==="all"||recipe.type===preference)).map(recipe=>{const available=recipe.ingredients.filter(hasIngredient),missing=recipe.ingredients.filter(name=>!hasIngredient(name)),urgent=available.filter(name=>inventory.some(item=>hasIngredient(name)&&normalizeName(item.name).includes(normalizeName(name))&&daysUntil(item.expiry)<=3)).length,score=available.length/recipe.ingredients.length*70+urgent*12-missing.length*9+(recipe.minutes<=limit?8:0);return{...recipe,available,missing,score:Math.round(score)}}).sort((a,b)=>b.score-a.score||a.missing.length-b.missing.length)}
function planMeal(){rankedRecipes=rankRecipes();if(!rankedRecipes.length){document.querySelector("#mealResult").innerHTML='<p class="empty-state">这个时间与偏好组合暂时没有合适菜品，请放宽条件。</p>';document.querySelector("#mealAlternatives").replaceChildren();return null}activeRecipe=rankedRecipes[0];renderMeal(activeRecipe);renderAlternatives();return activeRecipe}
function renderMeal(recipe){const servings=document.querySelector("#servings").value,match=Math.round(recipe.available.length/recipe.ingredients.length*100);document.querySelector("#mealResult").innerHTML=`<article class="meal-card"><div class="meal-main"><div class="meal-top"><h3>${esc(recipe.name)}</h3><span class="match">${match}% 食材就绪</span></div><p>${esc(recipe.note)}</p><div class="meal-tags"><span>${recipe.minutes} 分钟</span><span>${servings} 人份</span><span>${recipe.type==="vegetarian"?"清淡素食":"高蛋白"}</span></div>${recipe.missing.length?`<p class="missing">还缺：${recipe.missing.map(esc).join("、")}</p>`:'<p>所需食材已经齐全，可以直接开始。</p>'}</div><div class="meal-actions"><button onclick="openCooking()">开始烹饪</button><button onclick="addMissing()">${recipe.missing.length?"缺少食材加入清单":"换一道菜"}</button></div></article>`}
function renderAlternatives(){const host=document.querySelector("#mealAlternatives"),others=rankedRecipes.filter(item=>item.id!==activeRecipe?.id).slice(0,2);host.innerHTML=others.map(item=>`<button class="alternative" onclick="chooseRecipe('${item.id}')"><span><strong>${esc(item.name)}</strong><small>${item.minutes} 分钟 · 缺 ${item.missing.length} 样</small></span><b>${item.score} 分</b></button>`).join("")}
window.chooseRecipe=id=>{const recipe=rankedRecipes.find(item=>item.id===id);if(!recipe)return;activeRecipe=recipe;renderMeal(recipe);renderAlternatives()};
document.querySelector("#planMeal").onclick=()=>{const result=planMeal();if(result)toast(`已为你选择${result.name}`)};document.querySelector("#quickPlan").onclick=()=>{planMeal();document.querySelector("#mealStudio").scrollIntoView({behavior:"smooth"})};
window.openCooking=()=>{if(!activeRecipe)return;if(activeRecipe.missing.length){toast("先把缺少的食材加入购物清单吧。");return}stopTimer();timerSeconds=0;renderTimer();document.querySelector("#cookTitle").textContent=activeRecipe.name;document.querySelector("#cookTime").textContent=`约 ${activeRecipe.minutes} 分钟`;document.querySelector("#cookServings").textContent=`${document.querySelector("#servings").value} 人份`;document.querySelector("#cookReady").textContent="食材已齐";document.querySelector("#cookSteps").innerHTML=activeRecipe.steps.map(step=>`<li>${esc(step)}</li>`).join("");document.querySelectorAll("#cookSteps li").forEach(item=>item.onclick=()=>item.classList.toggle("done"));document.querySelector("#cookDialog").showModal()};
function finishCooking(){if(!activeRecipe)return;const finishedName=activeRecipe.name;let rescued=0;for(const name of activeRecipe.ingredients){const item=inventory.find(entry=>normalizeName(entry.name).includes(normalizeName(name))||normalizeName(name).includes(normalizeName(entry.name)));if(!item)continue;if(daysUntil(item.expiry)<=3)rescued+=1;item.quantity=Math.round((item.quantity-1)*10)/10}inventory=inventory.filter(item=>item.quantity>0);savedCount+=rescued;history.unshift({id:Date.now(),name:finishedName,cookedAt:new Date().toISOString(),servings:Number(document.querySelector("#servings").value),rescued});history=history.slice(0,50);save();render();document.querySelector("#cookDialog").close();stopTimer();planMeal();toast(`完成${finishedName}，库存已经同步更新`)}
function renderTimer(){const minutes=Math.floor(timerSeconds/60),seconds=timerSeconds%60;document.querySelector("#timerDisplay").textContent=`${String(minutes).padStart(2,"0")}:${String(seconds).padStart(2,"0")}`;document.querySelector("#timerToggle").textContent=timerHandle?"暂停":"开始计时"}
function stopTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null}renderTimer()}
document.querySelector("#timerToggle").onclick=()=>{if(timerHandle)stopTimer();else{timerHandle=setInterval(()=>{timerSeconds+=1;renderTimer()},1000);renderTimer()}};document.querySelector("#timerReset").onclick=()=>{stopTimer();timerSeconds=0;renderTimer()};document.querySelector("#closeCook").onclick=()=>{document.querySelector("#cookDialog").close();stopTimer()};document.querySelector("#finishCook").onclick=finishCooking;
window.addMissing=()=>{if(!activeRecipe)return;if(!activeRecipe.missing.length){const index=rankedRecipes.findIndex(item=>item.id===activeRecipe.id);activeRecipe=rankedRecipes[(index+1)%rankedRecipes.length];renderMeal(activeRecipe);renderAlternatives();return}for(const name of activeRecipe.missing)if(!shopping.some(item=>normalizeName(item.name)===normalizeName(name)))shopping.push({id:nextId(shopping),name,bought:false});save();render();toast("缺少的食材已加入购物清单")};

document.querySelector("#shoppingForm").onsubmit=event=>{event.preventDefault();const input=event.target.elements.item,name=input.value.trim();if(!name)return;shopping.push({id:nextId(shopping),name:name.slice(0,50),bought:false});input.value="";save();render();toast("已加入购物清单")};
window.toggleShopping=id=>{const item=shopping.find(entry=>entry.id===id);if(item)item.bought=!item.bought;save();render()};window.removeShopping=id=>{shopping=shopping.filter(item=>item.id!==id);save();render()};document.querySelector("#clearBought").onclick=()=>{shopping=shopping.filter(item=>!item.bought);save();render();toast("已清理买到的项目")};
document.querySelectorAll("[data-filter]").forEach(button=>button.onclick=()=>{inventoryFilter=button.dataset.filter;document.querySelectorAll("[data-filter]").forEach(item=>item.classList.toggle("active",item===button));renderInventory()});
document.querySelector("#inventorySearch").oninput=event=>{inventorySearch=event.target.value;renderInventory()};document.querySelector("#inventorySort").onchange=event=>{inventorySort=event.target.value;renderInventory()};
document.querySelectorAll("[data-scroll]").forEach(button=>button.onclick=()=>{document.querySelectorAll(".nav-item").forEach(item=>item.classList.toggle("active",item===button));document.querySelector(`#${button.dataset.scroll}`).scrollIntoView({behavior:"smooth"})});

document.querySelector("#clearHistory").onclick=()=>{if(!history.length){toast("目前没有用餐记录");return}if(!confirm("清空全部用餐记录吗？"))return;history=[];save();render();toast("用餐记录已清空")};
document.querySelector("#resetDemo").onclick=()=>{if(!confirm("恢复示例会替换当前食材、购物清单和用餐记录，建议先导出档案。继续吗？"))return;inventory=createDemo();shopping=[{id:1,name:"燕麦",bought:false},{id:2,name:"酸奶",bought:true}];history=[];savedCount=0;activeRecipe=null;save();render();document.querySelector("#mealResult").innerHTML='<p class="empty-state">选择时间与偏好，让 Agent 从现有食材中安排一顿饭。</p>';document.querySelector("#mealAlternatives").replaceChildren();toast("已恢复示例冰箱")};
function validImportItem(item){return item&&Number.isFinite(Number(item.id))&&String(item.name||"").trim()&&Number(item.quantity)>0&&/^\d{4}-\d{2}-\d{2}$/.test(String(item.expiry||""))}
document.querySelector("#exportData").onclick=()=>{const blob=new Blob([JSON.stringify({app:"FridgeFlow",version:2,exportedAt:new Date().toISOString(),inventory,shopping,history,savedCount},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`fridgeflow-${localDate(new Date())}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("冰箱档案已导出")};
document.querySelector("#importData").onclick=()=>document.querySelector("#importFile").click();document.querySelector("#importFile").onchange=async event=>{try{const file=event.target.files[0];if(!file)return;const data=JSON.parse(await file.text());if(data.app!=="FridgeFlow"||!Array.isArray(data.inventory)||!Array.isArray(data.shopping)||data.inventory.length>300||data.shopping.length>300||!data.inventory.every(validImportItem))throw new Error();inventory=data.inventory.map(item=>({...item,id:Number(item.id),name:String(item.name).slice(0,50),quantity:Number(item.quantity)}));shopping=data.shopping.map(item=>({id:Number(item.id),name:String(item.name||"").slice(0,50),bought:Boolean(item.bought)}));history=Array.isArray(data.history)?data.history.slice(0,50):[];savedCount=Math.max(0,Number(data.savedCount)||0);save();render();toast(`已导入 ${inventory.length} 种食材`)}catch{toast("无法识别这个 FridgeFlow 档案")}finally{event.target.value=""}};

function storeIngredient(input){const item={id:Date.now(),name:String(input.name||"").trim().slice(0,50),category:String(input.category||"其他"),quantity:Number(input.quantity||1),unit:String(input.unit||"份"),expiry:String(input.expiry||""),location:String(input.location||"冷藏室")};if(!item.name||!/^\d{4}-\d{2}-\d{2}$/.test(item.expiry)||!Number.isFinite(item.quantity)||item.quantity<=0)throw new Error("食材信息无效");inventory.push(item);save();render();return item}
function registerWebMcp(){const context=document.modelContext;if(!context?.registerTool)return;const tools=[
  {name:"list_pantry",title:"查看冰箱食材",description:"读取当前浏览器保存的食材、数量和到期状态。",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({count:inventory.length,items:inventory.map(item=>({...item,daysUntilExpiry:daysUntil(item.expiry)}))})},
  {name:"add_ingredient",title:"添加食材",description:"向 FridgeFlow 冰箱库存添加一种食材。",inputSchema:{type:"object",properties:{name:{type:"string",maxLength:50},category:{type:"string"},quantity:{type:"number",exclusiveMinimum:0},unit:{type:"string"},expiry:{type:"string",pattern:"^\\d{4}-\\d{2}-\\d{2}$"},location:{type:"string"}},required:["name","quantity","expiry"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{const item=storeIngredient(input);toast(`${item.name}已放入冰箱`);return{id:item.id,status:"saved"}}},
  {name:"plan_meal",title:"生成用餐建议",description:"根据当前冰箱库存和时间限制返回最合适的一道菜。",inputSchema:{type:"object",properties:{maxMinutes:{type:"number",enum:[15,30,45,60]},preference:{type:"string",enum:["all","vegetarian","protein"]}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(input.maxMinutes)document.querySelector("#timeLimit").value=String(input.maxMinutes);if(input.preference)document.querySelector("#preference").value=input.preference;const result=planMeal();return result?{name:result.name,minutes:result.minutes,available:result.available,missing:result.missing}:null}}
];for(const tool of tools){try{void Promise.resolve(context.registerTool(tool)).catch(()=>{})}catch{}}}

document.querySelector("#todayLabel").textContent=new Date().toLocaleDateString("zh-CN",{month:"long",day:"numeric",weekday:"long"});render();registerWebMcp();
